class Coupon:
    def __init__(self, code, percent_off):
        self.code = code
        self.percent_off = percent_off

    def apply(self, price):
        return price * (1 - self.percent_off / 100)

    @staticmethod
    def is_valid_code(code):
        return code.startswith('SALE-')
